 protected override void OnModelCreating(ModelBuilder b){b.Entity<Post>().HasIndex(x=>x.Slug).IsUnique(); b.Entity<Category>().HasIndex(x=>x.Slug).IsUnique(); b.Entity<Page>().HasIndex(x=>x.Slug).IsUnique(); b.Entity<CmsUser>().HasIndex(x=>x.UserName).IsUnique(); b.Entity<ExtensionPackage>().HasIndex(x=>x.PackageId).IsUnique();}
}
